// Ported from jaldi: jaldi-agent/src/calc/time.ts (2026-11-13). Keep the pair in step; see KO's note on sharing by copy.
/**
 * The time in a place, and its gap from Sydney (home). Places are
 * `places.json` (cities, airports, countries, generated by jaldi's
 * `scripts/places.ts`) plus the nicknames and states below; the arithmetic is
 * `Intl`, no library.
 */
import { SYDNEY_TZ } from '#lib/time.ts';
import places from './places.json' with { type: 'json' };

export interface Place {
	/** As shown: `Chicago`, `Pakistan`, `ORD Chicago`. */
	readonly name: string;
	readonly zone: string;
}

export const HOME: Place = { name: 'Sydney', zone: SYDNEY_TZ };

const NICKNAMES: Readonly<Record<string, string>> = {
	ny: 'new york',
	nyc: 'new york',
	'new york city': 'new york',
	manhattan: 'new york',
	brooklyn: 'new york',
	la: 'los angeles',
	sf: 'san francisco',
	sanfran: 'san francisco',
	'san fran': 'san francisco',
	frisco: 'san francisco',
	dc: 'washington, d.c.',
	washington: 'washington, d.c.',
	vegas: 'las vegas',
	philly: 'philadelphia',
	chi: 'chicago',
	ldn: 'london',
	khi: 'karachi',
	isb: 'islamabad',
	bombay: 'mumbai',
	calcutta: 'kolkata',
	madras: 'chennai',
	peking: 'beijing',
	saigon: 'ho chi minh city'
};

/** By hand: places too small for the generated list, and states. */
const ZONES: Readonly<Record<string, Place>> = {
	islamabad: { name: 'Islamabad', zone: 'Asia/Karachi' },
	california: { name: 'California', zone: 'America/Los_Angeles' },
	'new york state': { name: 'New York', zone: 'America/New_York' },
	texas: { name: 'Texas', zone: 'America/Chicago' },
	florida: { name: 'Florida', zone: 'America/New_York' },
	illinois: { name: 'Illinois', zone: 'America/Chicago' },
	washington_state: { name: 'Washington', zone: 'America/Los_Angeles' },
	colorado: { name: 'Colorado', zone: 'America/Denver' },
	arizona: { name: 'Arizona', zone: 'America/Phoenix' },
	hawaii: { name: 'Hawaii', zone: 'Pacific/Honolulu' },
	alaska: { name: 'Alaska', zone: 'America/Anchorage' },
	nsw: { name: 'New South Wales', zone: 'Australia/Sydney' },
	victoria: { name: 'Victoria', zone: 'Australia/Melbourne' },
	queensland: { name: 'Queensland', zone: 'Australia/Brisbane' },
	qld: { name: 'Queensland', zone: 'Australia/Brisbane' },
	wa: { name: 'Western Australia', zone: 'Australia/Perth' },
	'western australia': { name: 'Western Australia', zone: 'Australia/Perth' },
	'south australia': { name: 'South Australia', zone: 'Australia/Adelaide' },
	tasmania: { name: 'Tasmania', zone: 'Australia/Hobart' },
	pacific: { name: 'Pacific', zone: 'America/Los_Angeles' },
	eastern: { name: 'Eastern', zone: 'America/New_York' },
	central: { name: 'Central', zone: 'America/Chicago' },
	mountain: { name: 'Mountain', zone: 'America/Denver' },
	pst: { name: 'Pacific', zone: 'America/Los_Angeles' },
	est: { name: 'Eastern', zone: 'America/New_York' },
	cst: { name: 'Central', zone: 'America/Chicago' },
	utc: { name: 'UTC', zone: 'UTC' },
	gmt: { name: 'GMT', zone: 'UTC' }
};

const SHORT_COUNTRIES: Readonly<Record<string, string>> = {
	usa: 'united states',
	america: 'united states',
	uk: 'united kingdom',
	britain: 'united kingdom',
	england: 'united kingdom',
	uae: 'united arab emirates',
	emirates: 'united arab emirates'
};

interface Data {
	/** Lower-case ASCII name → zone, ISO country, the name as written. */
	readonly cities: Readonly<Record<string, readonly [string, string, string]>>;
	/** IATA → zone, the city it serves. */
	readonly airports: Readonly<Record<string, readonly [string, string]>>;
	/** ISO country → zone, the country's main one. */
	readonly countries: Readonly<Record<string, string>>;
}

const data = places as unknown as Data;
const regionNames = new Intl.DisplayNames(['en'], { type: 'region' });
let countryNames: Map<string, string> | undefined;

/** `table[key]` when it is the table's own: text never reaches `constructor` or `__proto__`. */
function own<T>(table: Readonly<Record<string, T>>, key: string): T | undefined {
	return Object.hasOwn(table, key) ? table[key] : undefined;
}

/**
 * What `text` names: a nickname, a city, a state, a country's name, an
 * airport (three letters) or a country's ISO code (two), in that order.
 */
export function place(text: string): Place | undefined {
	const typed = text.trim().toLowerCase().replace(/\s+/g, ' ');
	if (typed.length === 0) return undefined;
	const key = own(NICKNAMES, typed) ?? typed;
	const city = own(data.cities, key);
	if (city !== undefined) return { name: city[2], zone: city[0] };
	const byHand = own(ZONES, key) ?? own(ZONES, key.replace(/ /g, '_'));
	if (byHand !== undefined) return byHand;
	countryNames ??= new Map(
		Object.keys(data.countries).map((code) => [(regionNames.of(code) ?? code).toLowerCase(), code])
	);
	const said = own(SHORT_COUNTRIES, key) ?? key;
	const country = countryNames.get(said);
	if (country !== undefined)
		return {
			name: regionNames.of(country) ?? country,
			zone: own(data.countries, country) ?? 'UTC'
		};
	if (/^[a-z]{3}$/.test(typed)) {
		const airport = own(data.airports, typed.toUpperCase());
		if (airport !== undefined)
			return { name: `${typed.toUpperCase()} ${airport[1]}`, zone: airport[0] };
	}
	if (/^[a-z]{2}$/.test(typed)) {
		const zone = own(data.countries, typed.toUpperCase());
		if (zone !== undefined)
			return { name: regionNames.of(typed.toUpperCase()) ?? typed.toUpperCase(), zone };
	}
	return undefined;
}

/** One formatter per zone and kind: building one costs about 50 µs, using one about 2. */
const formatters = new Map<string, Intl.DateTimeFormat>();
function formatter(kind: 'offset' | 'wall', zone: string): Intl.DateTimeFormat {
	const key = `${kind} ${zone}`;
	let made = formatters.get(key);
	if (made === undefined) {
		made =
			kind === 'offset'
				? new Intl.DateTimeFormat('en', { timeZone: zone, timeZoneName: 'longOffset' })
				: new Intl.DateTimeFormat('en-GB', {
						timeZone: zone,
						hourCycle: 'h23',
						hour: '2-digit',
						minute: '2-digit',
						weekday: 'short',
						year: 'numeric',
						month: '2-digit',
						day: '2-digit'
					});
		formatters.set(key, made);
	}
	return made;
}

/** Minutes `zone` is ahead of UTC at `at`. */
function offset(zone: string, at: number): number {
	const part =
		formatter('offset', zone)
			.formatToParts(at)
			.find((p) => p.type === 'timeZoneName')?.value ?? 'GMT';
	const match = /GMT([+-])(\d{2}):?(\d{2})?/.exec(part);
	if (match === null) return 0;
	const minutes = Number(match[2]) * 60 + Number(match[3] ?? 0);
	return match[1] === '-' ? -minutes : minutes;
}

/** The wall clock in `zone` at `at`. */
function wall(
	zone: string,
	at: number
): { hour: number; minute: number; weekday: string; ymd: string } {
	const parts = Object.fromEntries(
		formatter('wall', zone)
			.formatToParts(at)
			.map((p) => [p.type, p.value])
	);
	return {
		hour: Number(parts.hour),
		minute: Number(parts.minute),
		weekday: parts.weekday ?? '',
		ymd: `${parts.year}-${parts.month}-${parts.day}`
	};
}

/** `3:20 pm`, `9 am` when on the hour. */
export function clock(hour: number, minute: number): string {
	const h = hour % 12 === 0 ? 12 : hour % 12;
	const half = hour < 12 ? 'am' : 'pm';
	return minute === 0 ? `${h} ${half}` : `${h}:${String(minute).padStart(2, '0')} ${half}`;
}

/** `6 h behind`, `5 h 30 m ahead of`, `the same time as`; a place follows. */
export function gap(minutes: number): string {
	if (minutes === 0) return 'the same time as';
	const size = Math.abs(minutes);
	const said = `${Math.floor(size / 60)} h${size % 60 === 0 ? '' : ` ${size % 60} m`}`;
	return `${said} ${minutes < 0 ? 'behind' : 'ahead of'}`;
}

/** What the tool says for a time query: the time there, and how it sits against Sydney. */
export interface TimeAnswer {
	readonly answer: string;
	readonly note?: string;
}

/**
 * The time in `placeText` (a city, state, country, airport code or nickname)
 * at `at` (now by default), and its gap from Sydney. Null when the place is
 * not one it knows. A leading `time in` is ignored.
 */
export function timeIn(placeText: string, at: Date = new Date()): TimeAnswer | null {
	const named = placeText.trim().replace(/^time\s+(?:in|at)\s+/i, '');
	const there = place(named);
	if (there === undefined) return null;
	const moment = at.getTime();
	const w = wall(there.zone, moment);
	const home = wall(HOME.zone, moment);
	const day = w.ymd === home.ymd ? '' : ` ${w.weekday}`;
	const answer = `${clock(w.hour, w.minute)}${day} in ${there.name}`;
	if (there.zone === HOME.zone)
		return { answer: `${clock(w.hour, w.minute)}${day} in ${there.name}` };
	const minutes = offset(there.zone, moment) - offset(HOME.zone, moment);
	const homeDay = w.ymd === home.ymd ? '' : ` ${home.weekday}`;
	return {
		answer,
		note: `${there.name} is ${gap(minutes)} ${HOME.name} (it is ${clock(home.hour, home.minute)}${homeDay} in ${HOME.name})`
	};
}
